import{_ as a,o as e,c as s,a5 as i}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"HotSpot 对象布局","description":"一个 Java 对象由对象头、实例字段和对齐填充组成。本文以 64 位 OpenJDK 21.0.12.1 HotSpot 为基线，解释如何计算对象大小、字段为什么不会按声明顺序排列，以及 Mark Word 如何复用同一批位来保存哈希、分代年龄和锁状态。","frontmatter":{},"headers":[],"relativePath":"java/02-jvm-runtime/chapter-03-object-layout.md","filePath":"java/02-jvm-runtime/chapter-03-object-layout.md"}'),l={name:"java/02-jvm-runtime/chapter-03-object-layout.md"};function d(n,t,c,r,o,p){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="hotspot-对象布局" tabindex="-1" data-src-line="1" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">HotSpot 对象布局 <a class="header-anchor" href="#hotspot-对象布局" aria-label="Permalink to &quot;HotSpot 对象布局&quot;">​</a></h1><p data-src-line="3" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">一个 Java 对象由对象头、实例字段和对齐填充组成。本文以 <strong>64 位 OpenJDK 21.0.12.1 HotSpot</strong> 为基线，解释如何计算对象大小、字段为什么不会按声明顺序排列，以及 Mark Word 如何复用同一批位来保存哈希、分代年龄和锁状态。</p><p data-src-line="5" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">以下计算固定使用 <code>-XX:+UseCompressedClassPointers</code>、<code>-XX:+UseCompressedOops</code> 和 <code>-XX:ObjectAlignmentInBytes=8</code>。不同 JVM、CPU 架构或启动参数会得到不同结果，实际值以目标 JVM 的输出为准。</p><h2 id="object-creation" tabindex="-1" data-src-line="7" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">1. new 一个对象发生了什么 <a class="header-anchor" href="#object-creation" aria-label="Permalink to &quot;1. new 一个对象发生了什么 {#object-creation}&quot;">​</a></h2><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">User user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p data-src-line="13" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">执行 <code>new User()</code> 时，HotSpot 需要保证 <code>User</code> 已完成创建实例所需的类准备工作，并遵守类初始化规则（详见<a href="./chapter-01-bytecode-classloading.html#initialization">类加载与初始化</a>）。对象分配完成后，实例字段必须具有 Java 规定的默认值（<code>int</code> 为 0、<code>boolean</code> 为 false、引用为 null），运行时还要写入对象头中的 Mark Word 和 Klass Pointer。随后执行构造方法 <code>&lt;init&gt;</code>，完成实例字段的显式初始化。</p><p data-src-line="15" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">常见的 TLAB 快速路径只需推进线程本地分配指针，但这不意味着所有对象都只走这一条路径。TLAB 耗尽后，HotSpot 可能申请新的 TLAB，也可能走慢路径；较大的对象还可能绕过 TLAB 直接分配。具体路径取决于对象大小、当前堆状态和 JVM 实现。TLAB 和 Eden 分配机制见<a href="./chapter-02-runtime-data-areas.html">运行时数据区与内存结构</a>。</p><h2 id="object-size" tabindex="-1" data-src-line="17" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">2. new Object() 为什么是 16 字节 <a class="header-anchor" href="#object-size" aria-label="Permalink to &quot;2. new Object() 为什么是 16 字节 {#object-size}&quot;">​</a></h2><p data-src-line="19" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">在本文的基线配置下，<code>new Object()</code> 没有实例字段，大小由对象头和最终填充决定：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Mark Word             8 字节</span></span>
<span class="line"><span>压缩后的 Klass Pointer 4 字节</span></span>
<span class="line"><span>实例字段              0 字节</span></span>
<span class="line"><span>尾部填充              4 字节</span></span>
<span class="line"><span>--------------------------------</span></span>
<span class="line"><span>对象总大小            16 字节</span></span></code></pre></div><p data-src-line="30" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">先按字段对齐规则确定每个字段的起始偏移，计算字段布局的结束位置，字段之间的空洞也要计入；最后将整个对象大小向上对齐到 <code>ObjectAlignmentInBytes</code> 的整数倍：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对象大小 = align_up(字段布局结束位置, ObjectAlignmentInBytes)</span></span></code></pre></div><p data-src-line="36" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">关闭压缩类指针后，Klass Pointer 变为 8 字节，<code>new Object()</code> 仍是 16 字节。这说明压缩指针改变的是头部结构，不一定改变每一种对象的最终大小；真正是否减少内存，要看字段和填充是否一起减少。</p><h2 id="_3-普通对象如何排布" tabindex="-1" data-src-line="38" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">3. 普通对象如何排布 <a class="header-anchor" href="#_3-普通对象如何排布" aria-label="Permalink to &quot;3. 普通对象如何排布&quot;">​</a></h2><p data-src-line="40" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">64 位 HotSpot 中，普通实例的基本结构如下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>字节偏移</span></span>
<span class="line"><span>0            8                 12                 16</span></span>
<span class="line"><span>+------------+-----------------+------------------+</span></span>
<span class="line"><span>| Mark Word  | Klass Pointer   | 实例字段或填充     |</span></span>
<span class="line"><span>|  8 字节     | 4 字节（压缩）    | 从偏移 12 开始    |</span></span>
<span class="line"><span>+------------+-----------------+------------------+</span></span>
<span class="line"><span>                                   ↑</span></span>
<span class="line"><span>                     字段自身仍要满足类型对齐</span></span></code></pre></div><h3 id="_3-1-对象头保存什么" tabindex="-1" data-src-line="53" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">3.1 对象头保存什么 <a class="header-anchor" href="#_3-1-对象头保存什么" aria-label="Permalink to &quot;3.1 对象头保存什么&quot;">​</a></h3><p data-src-line="55" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">对象头包含两部分：</p><ul data-src-line="57" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><li data-src-line="57" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><strong>Mark Word</strong>：64 位 HotSpot 固定占 8 字节，保存 identity hash、分代年龄和锁状态等可复用信息。</li><li data-src-line="58" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><strong>Klass Pointer</strong>：指向类元数据，让 HotSpot 判断对象的实际类型。启用压缩类指针时占 4 字节，否则占 8 字节。</li></ul><p data-src-line="60" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">类的 <code>static</code> 字段不属于对象实例，因此不会出现在这里。实例对象只保存当前类和父类的非静态字段。</p><h3 id="_3-2-压缩类指针与压缩引用不是一回事" tabindex="-1" data-src-line="62" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">3.2 压缩类指针与压缩引用不是一回事 <a class="header-anchor" href="#_3-2-压缩类指针与压缩引用不是一回事" aria-label="Permalink to &quot;3.2 压缩类指针与压缩引用不是一回事&quot;">​</a></h3><p data-src-line="64" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">两个开关压缩的是不同数据：</p><table tabindex="0"><thead data-src-line="66" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="66" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><th style="text-align:left;">开关</th><th style="text-align:left;">压缩对象</th><th style="text-align:left;">对布局的影响</th></tr></thead><tbody data-src-line="68" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="68" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>-XX:+UseCompressedClassPointers</code></td><td style="text-align:left;">对象头中的 <code>Klass*</code></td><td style="text-align:left;">Klass Pointer 从 8 字节变为 4 字节</td></tr><tr data-src-line="69" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>-XX:+UseCompressedOops</code></td><td style="text-align:left;">引用字段和引用数组元素</td><td style="text-align:left;"><code>Object</code> 引用从 8 字节变为 4 字节</td></tr></tbody></table><p data-src-line="71" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">在常见的 64 位 HotSpot 配置中，压缩类指针和压缩普通对象指针通常会启用，但实际值受 JVM 版本、堆配置和启动参数影响。不要根据操作系统位数或参数名称推断当前进程的布局；以目标 JVM 的 <code>-XX:+PrintFlagsFinal</code> 输出为准。</p><p data-src-line="73" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">压缩类指针留下的 4 字节并不总是尾部填充：</p><ul data-src-line="75" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><li data-src-line="75" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">普通实例可以把一个 <code>int</code> 或压缩引用放入偏移 12 的位置。</li><li data-src-line="76" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">数组头本身包含 <code>length</code> 字段。在本文的压缩类指针配置下，Klass Pointer 占 4 字节、<code>length</code> 紧随其后，因此元素区从偏移 16 开始。这是布局结果，不是运行时把原本空闲的字段临时拿来复用。</li></ul><h3 id="_3-3-实例字段按对齐和空洞排列" tabindex="-1" data-src-line="78" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">3.3 实例字段按对齐和空洞排列 <a class="header-anchor" href="#_3-3-实例字段按对齐和空洞排列" aria-label="Permalink to &quot;3.3 实例字段按对齐和空洞排列&quot;">​</a></h3><p data-src-line="80" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">以下对齐要求用于理解本文讨论的 HotSpot 布局示例，不是 Java 语言规范规定的跨 JVM 对象布局协议；具体字段偏移应以目标 JVM 的实际布局为准。</p><table tabindex="0"><thead data-src-line="82" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="82" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><th style="text-align:left;">字段类型</th><th style="text-align:left;">大小</th><th style="text-align:left;">对齐要求</th></tr></thead><tbody data-src-line="84" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="84" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>boolean</code>、<code>byte</code></td><td style="text-align:left;">1 字节</td><td style="text-align:left;">1 字节</td></tr><tr data-src-line="85" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>char</code>、<code>short</code></td><td style="text-align:left;">2 字节</td><td style="text-align:left;">2 字节</td></tr><tr data-src-line="86" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>int</code>、<code>float</code>、压缩引用</td><td style="text-align:left;">4 字节</td><td style="text-align:left;">4 字节</td></tr><tr data-src-line="87" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>long</code>、<code>double</code>、未压缩引用</td><td style="text-align:left;">8 字节</td><td style="text-align:left;">8 字节</td></tr></tbody></table><p data-src-line="89" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">HotSpot 会根据字段类型、大小和继承布局安排实例字段，并可能利用父类布局中的空洞。字段在内存中的顺序不必与源码声明顺序一致，父类字段也不保证全部位于子类字段之前。需要知道某个类的准确偏移时，应查看目标 JVM 的布局结果，而不是仅根据字段声明顺序或类型大小推算。<code>@Contended</code> 可以用于减少特定字段之间的伪共享，但其布局效果受 HotSpot 实现及相关参数影响，不能仅凭注解出现在源码中就推断最终增加的填充字节数。</p><p data-src-line="91" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">以基线配置为例：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Empty</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OneInt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value; }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OneLong</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">long</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value; }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TwoInts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> first; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> second; }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OneRef</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { Object value; }</span></span></code></pre></div><table tabindex="0"><thead data-src-line="101" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="101" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><th style="text-align:left;">类</th><th style="text-align:left;">布局计算</th><th style="text-align:right;">大小</th></tr></thead><tbody data-src-line="103" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="103" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>Empty</code></td><td style="text-align:left;">12 字节头部 + 4 字节尾部填充</td><td style="text-align:right;">16 字节</td></tr><tr data-src-line="104" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>OneInt</code></td><td style="text-align:left;">12 字节头部 + 4 字节 <code>int</code></td><td style="text-align:right;">16 字节</td></tr><tr data-src-line="105" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>OneLong</code></td><td style="text-align:left;">12 字节头部 + 4 字节对齐空洞 + 8 字节 <code>long</code></td><td style="text-align:right;">24 字节</td></tr><tr data-src-line="106" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>TwoInts</code></td><td style="text-align:left;">12 字节头部 + 2 × 4 字节 <code>int</code> + 4 字节尾部填充</td><td style="text-align:right;">24 字节</td></tr><tr data-src-line="107" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>OneRef</code></td><td style="text-align:left;">12 字节头部 + 4 字节压缩引用</td><td style="text-align:right;">16 字节</td></tr></tbody></table><p data-src-line="109" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">如果关闭压缩引用，<code>OneRef</code> 的引用字段占 8 字节，大小变为 24 字节。具体偏移属于 HotSpot 实现细节，不能作为跨版本 API；需要核对偏移时，应在目标 JVM 上测量。</p><h3 id="_3-4-对齐填充解决什么问题" tabindex="-1" data-src-line="111" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">3.4 对齐填充解决什么问题 <a class="header-anchor" href="#_3-4-对齐填充解决什么问题" aria-label="Permalink to &quot;3.4 对齐填充解决什么问题&quot;">​</a></h3><p data-src-line="113" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">在本文配置下，HotSpot 将对象大小按 8 字节对齐。这个限制决定了对象尾部可能出现填充；字段自身的对齐要求则决定了字段之间是否需要空洞。两种填充发生的位置不同，计算时都必须考虑。</p><p data-src-line="115" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">因此，两个字段的声明大小之和通常不等于实例数据区大小。例如，<code>OneLong</code> 的头部结束于偏移 12，而 <code>long</code> 必须从 8 的倍数开始，所以偏移 12 到 16 之间必须填充。</p><h2 id="_4-数组对象如何排布" tabindex="-1" data-src-line="117" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">4. 数组对象如何排布 <a class="header-anchor" href="#_4-数组对象如何排布" aria-label="Permalink to &quot;4. 数组对象如何排布&quot;">​</a></h2><p data-src-line="119" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">数组对象在普通对象头之后还要保存 <code>length</code>。在本文的压缩类指针配置下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0            8          12       16</span></span>
<span class="line"><span>+------------+----------+--------+----------------------+</span></span>
<span class="line"><span>| Mark Word  | Klass    | length | 元素 0, 元素 1, ...   |</span></span>
<span class="line"><span>|  8 字节     | 4 字节   | 4 字节  | 从偏移 16 开始        |</span></span>
<span class="line"><span>+------------+----------+--------+----------------------+</span></span></code></pre></div><p data-src-line="129" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">在本文的压缩类指针配置下，数组元素从偏移 16 开始，数组总大小按下式计算：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数组大小 = align_up(16 + 数组长度 × 元素大小, ObjectAlignmentInBytes)</span></span></code></pre></div><p data-src-line="135" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">这个简化公式只适用于本文给定的数组头布局。切换压缩类指针、对象对齐参数或 JVM 实现后，应重新确认数组头大小与元素起始偏移再计算总大小，不要直接沿用常数 16。</p><p data-src-line="137" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">基线配置下的例子：</p><table tabindex="0"><thead data-src-line="139" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="139" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><th style="text-align:left;">表达式</th><th style="text-align:left;">计算</th><th style="text-align:right;">大小</th></tr></thead><tbody data-src-line="141" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="141" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>new byte[1]</code></td><td style="text-align:left;"><code>align_up(16 + 1, 8)</code></td><td style="text-align:right;">24 字节</td></tr><tr data-src-line="142" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>new int[3]</code></td><td style="text-align:left;"><code>align_up(16 + 12, 8)</code></td><td style="text-align:right;">32 字节</td></tr><tr data-src-line="143" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>new long[3]</code></td><td style="text-align:left;"><code>align_up(16 + 24, 8)</code></td><td style="text-align:right;">40 字节</td></tr><tr data-src-line="144" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>new Object[3]</code></td><td style="text-align:left;"><code>align_up(16 + 3 × 4, 8)</code></td><td style="text-align:right;">32 字节</td></tr></tbody></table><p data-src-line="146" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">关闭压缩引用时，<code>Object[]</code> 的每个元素由 4 字节变为 8 字节，<code>new Object[3]</code> 变为 40 字节；基本类型数组不变。关闭压缩类指针会改变数组头，所有数组都需要重新计算。</p><h2 id="mark-word-states" tabindex="-1" data-src-line="148" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">5. Mark Word 如何编码锁状态 <a class="header-anchor" href="#mark-word-states" aria-label="Permalink to &quot;5. Mark Word 如何编码锁状态 {#mark-word-states}&quot;">​</a></h2><p data-src-line="150" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">Mark Word 不是一块固定字段，而是一组按状态复用的位。本节只解释对象头如何编码状态，不展开线程竞争、锁膨胀和解锁的完整过程；这些过程需要结合锁记录、Monitor 和具体 JDK 版本理解。OpenJDK 21 的 64 位普通对象格式为：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>位范围       63..39       38..8       7       6..3       2       1..0</span></span>
<span class="line"><span>字段         unused:25    hash:31     gap     age:4      gap     lock:2</span></span></code></pre></div><ul data-src-line="157" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><li data-src-line="157" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><code>hash</code> 区域用于保存对象的 identity hash。该值尚未生成或尚未写入对象头时，对应位可以为 0。调用对象重写后的 <code>hashCode()</code> 不一定会生成 identity hash；需要获取对象身份哈希时，使用 <code>System.identityHashCode(obj)</code>。身份哈希与业务哈希值不是同一个概念。</li><li data-src-line="158" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><code>age</code> 占 4 位，保存对象的分代年龄，取值范围 0～15。在采用分代回收的收集器中，对象在年轻代回收中存活后，年龄通常会增长；达到有效晋升阈值后，对象可能晋升到老年代。<code>MaxTenuringThreshold=15</code> 是上限，实际阈值还受收集器配置和 Survivor 区使用情况影响，不保证所有对象都恰好在同一年龄晋升。</li><li data-src-line="159" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">最低两位 <code>lock</code> 标识对象头当前采用的状态，它是状态的标记，不是完整的锁实现说明：</li></ul><table tabindex="0"><thead data-src-line="161" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="161" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><th style="text-align:left;"><code>lock</code></th><th style="text-align:left;">状态</th><th style="text-align:left;">含义</th></tr></thead><tbody data-src-line="163" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="163" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>01</code></td><td style="text-align:left;">普通对象头</td><td style="text-align:left;">未处于轻量级锁定或 Monitor 膨胀状态，保存 identity hash、分代年龄</td></tr><tr data-src-line="164" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>00</code></td><td style="text-align:left;">轻量级锁定状态</td><td style="text-align:left;">传统栈锁实现中，对象头关联线程栈上的锁记录，原 Mark Word 保存在 displaced header 中；其他实现以对应版本为准</td></tr><tr data-src-line="165" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>10</code></td><td style="text-align:left;">Monitor 膨胀状态</td><td style="text-align:left;">Mark Word 中保存与 <code>ObjectMonitor</code> 关联的信息</td></tr><tr data-src-line="166" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>11</code></td><td style="text-align:left;">标记状态</td><td style="text-align:left;">用于 GC 等运行时操作，不是对象保持的普通业务状态</td></tr></tbody></table><p data-src-line="168" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">Mark Word 的位会随对象状态改变含义，因此不能把普通状态下的位布局直接套用到锁定状态。HotSpot 必须在轻量级锁记录或膨胀后的 Monitor 等结构中保留必要的对象头信息，才能在解锁或恢复对象头时维持对象原有的身份哈希等语义。具体信息保存在哪里，取决于所用 JDK 的锁实现。</p><p data-src-line="170" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">偏向锁属于历史实现，不进入本文的 OpenJDK 21 基线。旧版 HotSpot 的 Mark Word 格式可能包含偏向锁标记，并在偏向状态下保存线程标识和 Epoch。OpenJDK 8u504 的 64 位格式含 <code>biased_lock</code> 位；OpenJDK 17 仍接受 <code>-XX:+UseBiasedLocking</code>，但会提示该选项自 15 起已弃用；OpenJDK 21.0.12.1 的 HotSpot 源码不再包含偏向锁格式。</p><p data-src-line="172" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">锁记录、Monitor 膨胀和锁升级的运行过程见 <a href="./../03-java-concurrency/chapter-06-synchronized.html#synchronized-lock-optimization"><code>synchronized</code> 锁优化</a>。</p><h2 id="verify-layout" tabindex="-1" data-src-line="174" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">6. 如何核对目标 JVM 的布局 <a class="header-anchor" href="#verify-layout" aria-label="Permalink to &quot;6. 如何核对目标 JVM 的布局 {#verify-layout}&quot;">​</a></h2><p data-src-line="176" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">先核对决定布局的参数：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -XX:+PrintFlagsFinal</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -version</span></span></code></pre></div><p data-src-line="182" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">重点检查以下输出是否与预期一致：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bool  UseCompressedClassPointers  = true</span></span>
<span class="line"><span>bool  UseCompressedOops           = true</span></span>
<span class="line"><span>int   ObjectAlignmentInBytes      = 8</span></span></code></pre></div><p data-src-line="190" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">需要查看具体偏移和字段间距时，使用 <a href="https://github.com/openjdk/jol" target="_blank" rel="noreferrer">OpenJDK JOL</a>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/jol-cli-full.jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> internals</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> java.lang.Object</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/jol-cli-full.jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> internals</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.example.User</span></span></code></pre></div><p data-src-line="197" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">查看自定义类之前，先编译该类并确保它位于当前 classpath 或 JOL 能访问的类路径中。<code>com.example.User</code> 是示例类名，需替换成实际类名；如果类依赖其他类型，也要确保相应依赖可用。</p><p data-src-line="199" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">JOL 必须运行在与目标布局一致的 JVM 配置上，它输出的是当前进程的测量结果，不是跨版本保证。同理，<code>-XX:+PrintFlagsFinal</code> 要对应目标应用实际使用的 JVM 参数；单独运行不带应用参数的 <code>java -XX:+PrintFlagsFinal -version</code>，只能说明这次命令启动的 JVM 配置，不一定代表线上进程。</p><p data-src-line="201" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><code>-XX:+PrintFieldLayout</code> 只存在于 HotSpot 的 debug 或 notproduct 构建中；普通发行版会提示该选项不可用，不能把它当作通用布局检查命令。</p><blockquote data-src-line="203" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><p data-src-line="203" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">版本依据：布局计算核对 OpenJDK <code>jdk-21.0.12.1-ga</code> 中的 <code>markWord.hpp</code>、<code>instanceOop.hpp</code>、<code>arrayOop.hpp</code>、<code>fieldLayoutBuilder.cpp</code> 和 <code>globals.hpp</code>；偏向锁历史格式对照 <code>jdk8u504-ga</code> 中的 <code>markOop.hpp</code>，核对日期为 2026-10-09。</p></blockquote><blockquote data-src-line="205" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><p data-src-line="205" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">本章解释对象在堆中的实际排布。对象分配区域和 TLAB 见<a href="./chapter-02-runtime-data-areas.html">运行时数据区与内存结构</a>，Mark Word 如何服务 GC 见<a href="./chapter-04-gc.html">垃圾回收</a>，锁状态的运行方式见 <a href="./../03-java-concurrency/chapter-06-synchronized.html#synchronized-lock-optimization"><code>synchronized</code> 锁优化</a>。</p></blockquote>`,66)])])}const j=a(l,[["render",d]]);export{m as __pageData,j as default};
